import json
with open('/app/resources/treasury_bulletin_1939_03.json') as f:
    data = json.load(f)
# Search through the JSON for any mention of pounds or exchange
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            search(v, path + '.' + k if path else k)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
    elif isinstance(obj, str):
        if 'pound' in obj.lower() or 'exchange' in obj.lower() or '1941' in obj:
            print(f'{path}: {obj[:200]}')

search(data)
"

